# 十二平均律：每升半音，频率 × 1.0595（≈2 的 1/12 次方）
f = 262          # 中央 C（do）的频率，单位 Hz
step = 1.0595    # 半音比例

costume("🎹")
say("从 do 开始，每升半音频率乘 " + step)

for i in range(0, 13):
    if i == 0:
        say("do  = " + f + " Hz")
    if i == 1:
        say("升do = " + f + " Hz")
    if i == 2:
        say("re  = " + f + " Hz")
    if i == 4:
        say("mi  = " + f + " Hz")
    if i == 5:
        say("fa  = " + f + " Hz")
    if i == 7:
        say("sol = " + f + " Hz")
    if i == 9:
        say("la  = " + f + " Hz")
    if i == 11:
        say("xi  = " + f + " Hz")
    if i == 12:
        say("高音do = " + f + " Hz（正好翻倍！）")
    f = f * step        # 每次乘上「半音密码」
    wait(0.2)

say("262 × 2 = 524：一个八度频率正好翻倍！")
